import React, { useEffect, useRef, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './VehicleDetail.css';

// ── FEATURE ICONS ──
const featureIcons = {
  'Sièges massants':      '◈',
  'Toit panoramique':     '◉',
  'Éclairage ambiant':    '◇',
  'IA Mercedes MBUX':     '◎',
  'Hyperscreen OLED':     '▣',
  'Autonomie 770 km':     '◈',
  'Recharge rapide':      '⚡',
  'Conduite autonome':    '◉',
  'Pack Sport Chrono':    '◷',
  'Échappement sport':    '◈',
  'Launch Control':       '◎',
  'Intérieur cuir premium':'◇',
};

// ── PARTICLES ──
function Particles() {
  const particles = Array.from({ length: 18 }, (_, i) => ({
    id: i,
    x:     `${Math.random() * 100}%`,
    y:     `${50 + Math.random() * 50}%`,
    dur:   `${4 + Math.random() * 6}s`,
    delay: `${Math.random() * 6}s`,
  }));

  return (
    <div className="vd-hero__particles">
      {particles.map(p => (
        <div
          key={p.id}
          className="vd-particle"
          style={{
            '--x':     p.x,
            '--y':     p.y,
            '--dur':   p.dur,
            '--delay': p.delay,
          }}
        />
      ))}
    </div>
  );
}

export default function VehicleDetail() {
  const { id } = useParams();
  const { isAuthenticated } = useAuth();
  const heroRef    = useRef(null);
  const cursorRef  = useRef(null);
  const [loaded, setLoaded] = useState(false);

  // ── CURSOR GLOW ──
  useEffect(() => {
    const move = (e) => {
      if (cursorRef.current) {
        cursorRef.current.style.left = e.clientX + 'px';
        cursorRef.current.style.top  = e.clientY + 'px';
      }
    };
    window.addEventListener('mousemove', move);
    return () => window.removeEventListener('mousemove', move);
  }, []);

  // ── PARALLAX ──
  useEffect(() => {
    const hero = heroRef.current;
    if (!hero) return;
    const bg = hero.querySelector('.vd-hero__bg img');
    const content = hero.querySelector('.vd-hero__content');

    const onScroll = () => {
      const y = window.scrollY;
      if (bg)      bg.style.transform      = `scale(1.05) translateY(${y * 0.25}px)`;
      if (content) content.style.transform = `translateY(${y * 0.12}px)`;
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, [loaded]);

  // ── INTERSECTION OBSERVER for specs ──
  useEffect(() => {
    const items = document.querySelectorAll('.vd-spec-item, .vd-feature');
    const obs = new IntersectionObserver(
      (entries) => entries.forEach((e, i) => {
        if (e.isIntersecting) {
          e.target.style.transitionDelay = `${i * 0.07}s`;
          e.target.style.opacity  = '1';
          e.target.style.transform = 'translateY(0)';
        }
      }),
      { threshold: 0.1 }
    );
    items.forEach(el => {
      el.style.opacity   = '0';
      el.style.transform = 'translateY(24px)';
      el.style.transition = 'opacity 0.7s cubic-bezier(0.16,1,0.3,1), transform 0.7s cubic-bezier(0.16,1,0.3,1)';
      obs.observe(el);
    });
    return () => obs.disconnect();
  }, [loaded]);

  // ── VEHICLES DATA ──
  const vehicles = [
    {
      id: 'classe-s',
      brand: 'Mercedes-Benz',
      model: 'Classe S',
      image: '/images/classe-s.png',
      category: 'Berline de Luxe',
      power: '367 ch',
      accent: '#C9A84C',
      color: '#0d1117',
      acceleration: '4.9s',
      fuel: 'Hybride',
      speed: '250 km/h',
      price: '145 000',
      tagline: 'Le luxe réinventé',
      features: ['Sièges massants','Toit panoramique','Éclairage ambiant','IA Mercedes MBUX'],
    },
    {
      id: 'eqs-580',
      brand: 'Mercedes-Benz',
      model: 'EQS 580',
      image: '/images/MercedesEQS580.png',
      category: '100% Électrique',
      power: '523 ch',
      accent: '#00D1FF',
      color: '#040d12',
      acceleration: '4.3s',
      fuel: 'Électrique',
      speed: '210 km/h',
      price: '165 000',
      tagline: "L'avenir du luxe électrique",
      features: ['Hyperscreen OLED','Autonomie 770 km','Recharge rapide','Conduite autonome'],
    },
    {
      id: '911-carrera-s',
      brand: 'Porsche',
      model: '911 Carrera S',
      image: '/images/porsche911.png',
      category: 'Sport Légendaire',
      power: '450 ch',
      accent: '#ff3b30',
      color: '#0f0404',
      acceleration: '3.7s',
      fuel: 'Essence',
      speed: '308 km/h',
      price: '182 000',
      tagline: 'La sportivité absolue',
      features: ['Pack Sport Chrono','Échappement sport','Launch Control','Intérieur cuir premium'],
    },
  ];

  const vehicle = vehicles.find(v => v.id === id);

  if (!vehicle) {
    return (
      <main className="page-wrapper vd-404">
        <div>
          <h2 style={{ fontFamily:'Cormorant Garamond, serif', fontSize: 80, color:'var(--gold)', fontWeight: 300 }}>
            404
          </h2>
          <p style={{ fontFamily:'Josefin Sans, sans-serif', letterSpacing: 4, fontSize: 10, color:'var(--white-muted)', marginTop: 12, textTransform:'uppercase' }}>
            Véhicule introuvable
          </p>
          <Link to="/vehicles" className="btn-gold-luxury" style={{ marginTop: 40, display:'inline-flex' }}>
            Retour à la collection
          </Link>
        </div>
      </main>
    );
  }

  return (
    <main className="page-wrapper vd-page">

      {/* CURSOR GLOW */}
      <div className="vd-cursor-glow" ref={cursorRef} />

      {/* ── HERO ── */}
      <div
        ref={heroRef}
        className={`vd-hero ${loaded ? 'is-loaded' : ''}`}
        style={{ background: `linear-gradient(135deg, ${vehicle.color} 0%, #050505 100%)` }}
      >
        {/* BG IMAGE */}
        <div className="vd-hero__bg">
          <img
            src={vehicle.image}
            alt={vehicle.model}
            onLoad={() => setLoaded(true)}
          />
        </div>

        {/* OVERLAY */}
        <div className="vd-hero__overlay" />

        {/* GRID */}
        <div className="vd-hero__grid" />

        {/* PARTICLES */}
        <Particles />

        {/* CONTENT */}
        <div className="vd-hero__content">

          <Link to="/vehicles" className="vd-back">
            Retour à la collection
          </Link>

          <span className="vd-hero__category">{vehicle.category}</span>

          <span className="vd-hero__brand">{vehicle.brand}</span>

          <h1 className="vd-hero__model">{vehicle.model}</h1>

          <div className="vd-hero__divider">
            <div className="vd-hero__divider-gem" style={{ background: vehicle.accent, boxShadow: `0 0 12px ${vehicle.accent}` }} />
          </div>

          <p className="vd-hero__tagline">{vehicle.tagline}</p>

          <div className="vd-hero__price-badge">
            <span className="vd-price-from">Prix de départ</span>
            <span className="vd-price-amount">
              {vehicle.price}
              <span>€</span>
            </span>
          </div>
        </div>

        {/* SCROLL INDICATOR */}
        <div className="vd-scroll-indicator">
          <div className="vd-scroll-line" />
          <span className="vd-scroll-text">Découvrir</span>
        </div>
      </div>

      {/* ── SPECS BAR ── */}
      <section className="vd-details">
        <div className="vd-specs-bar">
          {[
            { label: 'Puissance',   value: vehicle.power },
            { label: '0 → 100',     value: vehicle.acceleration },
            { label: 'Vitesse max', value: vehicle.speed },
            { label: 'Énergie',     value: vehicle.fuel },
          ].map((s) => (
            <div key={s.label} className="vd-spec-item">
              <span className="vd-spec-item__value" style={{ color: vehicle.accent }}>
                {s.value}
              </span>
              <span className="vd-spec-item__label">{s.label}</span>
            </div>
          ))}
        </div>

        {/* ── BODY ── */}
        <div className="vd-body">

          {/* FEATURES */}
          <div className="vd-features">
            <h3 className="vd-section-title">Équipements Clés</h3>
            <div className="vd-features-grid">
              {vehicle.features.map((f) => (
                <div key={f} className="vd-feature">
                  <div
                    className="vd-feature__icon"
                    style={{ color: vehicle.accent }}
                  >
                    {featureIcons[f] || '◈'}
                  </div>
                  {f}
                </div>
              ))}
            </div>
          </div>

          {/* CTA PANEL */}
          <div className="vd-cta-panel">
            <div className="vd-price-block">
              <span className="vd-price-label">Prix de départ</span>
              <div className="vd-price-value">
                {vehicle.price}
                <span className="vd-price-currency">€</span>
              </div>
              <span className="vd-price-note">Financement · LOA · Crédit</span>
            </div>

            {isAuthenticated ? (
              <div className="vd-actions">
                <Link to="/contact" className="btn-gold-luxury">
                  Demander un essai
                </Link>
                <Link to="/contact" className="btn-outline-luxury">
                  Configurer mon véhicule
                </Link>
              </div>
            ) : (
              <div className="vd-auth-prompt">
                <p>
                  Connectez-vous pour accéder à la configuration,
                  l'essai routier et les offres personnalisées.
                </p>
                <Link to="/login" className="btn-gold-luxury" style={{ marginTop: 28, display:'flex' }}>
                  Se connecter
                </Link>
              </div>
            )}
          </div>

        </div>
      </section>
    </main>
  );
}
